from __future__ import annotations
import random
from typing import Sequence

def tsha(h: Sequence[float], m: Sequence[float]) -> float:
    """Single-key tropical hash: min_i (m_i + h_i)."""
    return min(mi + hi for mi, hi in zip(m, h))

def argmin_index(h: Sequence[float], m: Sequence[float]) -> int:
    best_i, best_v = 0, m[0] + h[0]
    for i in range(1, len(m)):
        v = m[i] + h[i]
        if v < best_v:
            best_i, best_v = i, v
    return best_i

def sup_norm(m: Sequence[float], mp: Sequence[float]) -> float:
    return max(abs(a - b) for a, b in zip(m, mp))

def verify_stability(k: int = 32, trials: int = 20000, seed: int = 0) -> None:
    rng = random.Random(seed)
    worst = 0.0
    for _ in range(trials):
        h = [rng.uniform(-10, 10) for _ in range(k)]
        m = [rng.uniform(-10, 10) for _ in range(k)]
        mp = [rng.uniform(-10, 10) for _ in range(k)]
        d = sup_norm(m, mp)
        if d == 0:
            continue
        worst = max(worst, abs(tsha(h, m) - tsha(h, mp)) / d)
    h = [rng.uniform(-10, 10) for _ in range(k)]
    m = [rng.uniform(-10, 10) for _ in range(k)]
    w = argmin_index(h, m)
    ms = list(m); ms[w] += 0.5
    sharp = abs(tsha(h, m) - tsha(h, ms)) / sup_norm(m, ms)
    print(f"worst ratio = {worst:.6f} (<= 1); sharp ratio = {sharp:.6f} (= 1)")

if __name__ == "__main__":
    verify_stability()

from __future__ import annotations
import random
from typing import List, Sequence

def tsha(h: Sequence[float], m: Sequence[float]) -> float:
    return min(mi + hi for mi, hi in zip(m, h))

def argmin_index(h: Sequence[float], m: Sequence[float]) -> int:
    best_i, best_v = 0, m[0] + h[0]
    for i in range(1, len(m)):
        v = m[i] + h[i]
        if v < best_v:
            best_i, best_v = i, v
    return best_i

def collide(h: Sequence[float], m: Sequence[float], delta: float = 1.0) -> List[float]:
    """Return m' != m with TSHA(h, m') = TSHA(h, m); requires k >= 2."""
    if len(m) < 2:
        raise ValueError("k must be >= 2")
    i_star = argmin_index(h, m)
    k_star = 1 if i_star == 0 else 0
    mp = list(m); mp[k_star] += delta
    return mp

def verify_collisions(k: int = 32, trials: int = 10000, seed: int = 1) -> None:
    rng = random.Random(seed)
    ok = 0
    for _ in range(trials):
        h = [rng.uniform(-10, 10) for _ in range(k)]
        m = [rng.uniform(-10, 10) for _ in range(k)]
        mp = collide(h, m, rng.uniform(0.1, 5.0))
        if mp != list(m) and tsha(h, mp) == tsha(h, m):
            ok += 1
    print(f"valid collisions: {ok}/{trials} = {ok / trials:.4f}")

if __name__ == "__main__":
    verify_collisions()

from __future__ import annotations
import random
from typing import Sequence

def tsha(h: Sequence[float], m: Sequence[float]) -> float:
    return min(mi + hi for mi, hi in zip(m, h))

def argmin_index(h: Sequence[float], m: Sequence[float]) -> int:
    best_i, best_v = 0, m[0] + h[0]
    for i in range(1, len(m)):
        v = m[i] + h[i]
        if v < best_v:
            best_i, best_v = i, v
    return best_i

def separation_rate(k: int, trials: int, rng: random.Random) -> float:
    separated = 0
    for _ in range(trials):
        h = [rng.uniform(-10, 10) for _ in range(k)]
        m = [rng.uniform(-10, 10) for _ in range(k)]
        i_star = argmin_index(h, m)
        j = rng.choice([i for i in range(k) if i != i_star])
        mp = list(m); mp[j] += rng.uniform(0.1, 5.0)
        hp = [rng.uniform(-10, 10) for _ in range(k)]
        if tsha(hp, mp) != tsha(hp, m):
            separated += 1
    return separated / trials

def main(trials: int = 20000, seed: int = 2) -> None:
    rng = random.Random(seed)
    for k in (8, 16, 32, 64, 128):
        r = separation_rate(k, trials, rng)
        print(f"k={k:4d}  sep_rate={r:.5f}  k*rate={k * r:.3f}")

if __name__ == "__main__":
    main()

