function INVERT_SINGLE(h, y, lower, upper):
    active  <- { i : lower[i] + h[i] <= y <= upper[i] + h[i] }
    if active is empty: return INFEASIBLE
    if exists i with upper[i] + h[i] < y: return INFEASIBLE
    a <- any element of active
    m[a] <- y - h[a]
    for i != a: m[i] <- clamp(y - h[i], lower[i], upper[i])
    return m
